using System;
using System.Linq;
using UnityEditor;
using UnityEngine;
using MultiFPS.Gameplay.RiftCombat;
namespace ROM.EditorTools {
public static class WarriorProgressionBuilder {
 const string Root="Assets/ROM/Characters/Warrior";
 static T Asset<T>(string path)where T:ScriptableObject{var a=AssetDatabase.LoadAssetAtPath<T>(path);if(!a){a=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(a,path);}return a;}
 static Material Mat(string name,Color color,float metallic){string path=Root+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",.35f);EditorUtility.SetDirty(m);return m;}
 static GameObject Shield(){var existing=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/WarriorShield.prefab");if(existing)return existing;var root=new GameObject("Warrior round shield prototype");var steel=Mat("Shield steel",new Color(.24f,.28f,.34f),.85f);var wood=Mat("Shield wood",new Color(.18f,.075f,.035f),0);Part(root,"Steel rim",new Vector3(.68f,.045f,.68f),steel);Part(root,"Wooden face",new Vector3(.60f,.05f,.60f),wood);var boss=Part(root,"Steel boss",new Vector3(.18f,.065f,.18f),steel);boss.transform.localPosition=Vector3.up*.05f;var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/WarriorShield.prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
 static GameObject Part(GameObject parent,string name,Vector3 scale,Material material){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(parent.transform,false);g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=material;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static WeaponDefinition Sword(){var existing=AssetDatabase.LoadAssetAtPath<WeaponDefinition>(Root+"/WarriorSword.asset");if(existing&&existing.Model)return existing;var root=new GameObject("Warrior one handed sword");var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Free medieval weapons/Prefabs/Sword_OH.prefab");if(!source)throw new Exception("Sword_OH missing");var model=UnityEngine.Object.Instantiate(source,root.transform);model.transform.localPosition=Vector3.zero;model.transform.localRotation=Quaternion.identity;foreach(var r in model.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(original=>{var path=Root+"/Sword "+original.name+" URP.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));if(original.HasProperty("_MainTex"))mat.SetTexture("_BaseMap",original.GetTexture("_MainTex"));mat.SetFloat("_Metallic",.7f);mat.SetFloat("_Smoothness",.4f);AssetDatabase.CreateAsset(mat,path);}return mat;}).ToArray();}foreach(var col in model.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(col);var renderers=model.GetComponentsInChildren<Renderer>();var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);var weapon=Asset<WeaponDefinition>(Root+"/WarriorSword.asset");weapon.Id="warrior-sword";weapon.DisplayName="Espada de una mano";weapon.Model=PrefabUtility.SaveAsPrefabAsset(root,Root+"/WarriorSword.prefab");weapon.Scale=Vector3.one*.95f/Mathf.Max(bounds.size.x,Mathf.Max(bounds.size.y,bounds.size.z));weapon.Rotation=AssetDatabase.LoadAssetAtPath<WeaponDefinition>(Root+"/WarriorAxe.asset").Rotation;weapon.DamageMultiplier=.85f;weapon.AllowedClasses=new[]{"warrior"};EditorUtility.SetDirty(weapon);UnityEngine.Object.DestroyImmediate(root);return weapon;}
 [MenuItem("ROM/Progresión/Preparar Warrior, talentos y equipo")]
 public static void Build(){var tuning=Asset<WarriorProgressionDefinition>("Assets/ROM/Resources/WarriorProgression.asset");tuning.Sword=Sword();var shield=Asset<WeaponDefinition>(Root+"/WarriorShield.asset");shield.Model=Shield();shield.Socket=HumanBodyBones.LeftHand;tuning.Sword.AdditionalEquipment=new[]{shield};EditorUtility.SetDirty(shield);EditorUtility.SetDirty(tuning.Sword);EditorUtility.SetDirty(tuning);var species=AssetDatabase.LoadAssetAtPath<SpeciesDefinition>("Assets/ROM/Combat/Nertor.asset");var c=species.Classes[0];var basic=c.BasicAttack;var sweep=Asset<AbilityDefinition>("Assets/ROM/Combat/CleavingSweep.asset");EditorUtility.CopySerialized(basic,sweep);sweep.name="CleavingSweep";sweep.Id="cleaving-sweep";sweep.DisplayName="Barrido";sweep.Description="Tajo frontal que alcanza a todos los enemigos en el arco. Genera Furia. Independiente del autoataque.";sweep.Damage=22;sweep.Radius=3.6f;sweep.Arc=110;sweep.Cooldown=1.5f;sweep.ResourceGain=10;EditorUtility.SetDirty(sweep);
 var list=c.Abilities.Take(6).ToList();list.Add(sweep);c.Abilities=list.ToArray();EditorUtility.SetDirty(c);var leap=c.Abilities[3];leap.DisplayName="Salto de guerra";leap.Description="Desplazamiento hacia el objetivo o al frente, con daño de aterrizaje. Alcance máximo 12 m.";leap.Shape=AbilityShape.Circle;leap.Implemented=true;leap.Damage=45;leap.Radius=4;leap.Cooldown=12;leap.Cost=15;leap.CastDuration=.7f;leap.HitTime=.4f;leap.Animation=basic.Animation;leap.ImpactVfx=c.Abilities[1].ImpactVfx;leap.Icon=basic.Icon;leap.Stagger=.5f;EditorUtility.SetDirty(leap);
 var whirl=c.Abilities[4];whirl.DisplayName="Torbellino";whirl.Description="Cuatro impactos circulares durante 1,8 s. Movimiento al 55%.";whirl.Shape=AbilityShape.Circle;whirl.Implemented=true;whirl.Damage=18;whirl.Radius=4.5f;whirl.Cooldown=14;whirl.Cost=30;whirl.CastDuration=1.8f;whirl.HitTime=.2f;whirl.Animation=c.Abilities[0].Animation;whirl.ImpactVfx=c.Abilities[0].ImpactVfx;whirl.Icon=c.Abilities[0].Icon;EditorUtility.SetDirty(whirl);
 var stand=c.Abilities[5];stand.DisplayName="Última resistencia";stand.Description="Reduce un 50% el daño recibido durante 6 s.";stand.Shape=AbilityShape.Self;stand.Implemented=true;stand.Damage=0;stand.Cooldown=35;stand.Cost=20;stand.CastDuration=.6f;stand.HitTime=.1f;stand.BuffDuration=6;stand.Animation=c.Abilities[2].Animation;stand.ImpactVfx=c.Abilities[2].ImpactVfx;stand.Icon=c.Abilities[2].Icon;EditorUtility.SetDirty(stand);
 global::WarriorEquipmentSetup.Configure();AssetDatabase.SaveAssets();RiftGameplayHUDBuilder.Build();}
 public static void Run(){try{Build();Debug.Log("WARRIOR PROGRESSION BUILD PASSED");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}}
